	private static List<Statement> statements(boolean spill) {
		var values = SimpleValueFactory.getInstance();
		IRI predicate = values.createIRI("https://例え.テスト/名前/𝄞#predicate");
		Resource named = values.createIRI("urn:context:😀");
		Resource blankContext = values.createBNode("context-é-𐐀");
		List<Statement> result = new ArrayList<>();
		result.add(values.createStatement(values.createIRI("https://例え.テスト/路径/🧪#subject"), predicate,
				values.createIRI("urn:对象:𐐀")));
		result.add(values.createStatement(values.createBNode("subject-ø-🧬"), predicate,
				values.createBNode("object-π-𐐀"), blankContext));
		result.add(values.createStatement(values.createIRI("urn:lexical:plain"), predicate,
				values.createLiteral("\u0000Aé漢字😀"), named));
		result.add(values.createStatement(values.createIRI("urn:lexical:datatype"), predicate,
				values.createLiteral("023.00", values.createIRI("https://例え.テスト/型#😀"))));
		result.add(values.createStatement(values.createIRI("urn:lexical:language"), predicate,
				values.createLiteral("déjà 😀", "FR-ca"), named));
		result.add(values.createStatement(values.createIRI("urn:lexical:ltr"), predicate,
				values.createLiteral("left to right 😀", "EN-GB", Literal.BaseDirection.LTR), blankContext));
		result.add(values.createStatement(values.createIRI("urn:lexical:rtl"), predicate,
				values.createLiteral("שלום 𐐀", "HE", Literal.BaseDirection.RTL), named));
		String extended = "EN-x-" + "abcdefgh-".repeat(8) + "abcdefgh";
		assertTrue(extended.length() > 63);
		result.add(values.createStatement(values.createIRI("urn:lexical:long-language"), predicate,
				values.createLiteral("extended language é😀", extended)));
		result.add(values.createStatement(values.createIRI("urn:lexical:long-directional"), predicate,
				values.createLiteral("extended directional 😀", extended, Literal.BaseDirection.RTL), blankContext));
		if (spill) {
			result.add(values.createStatement(values.createIRI("urn:lexical:large"), predicate,
					values.createLiteral("large-𝄞-é-漢字-".repeat(8000)), named));
		}
		return result;
	}

	private static Map<String, Statement> physicalStatements(LmdbSailStore backing) {
		var values = SimpleValueFactory.getInstance();
		List<Statement> statements = new ArrayList<>();
		try (SailDataset dataset = backing.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
				var cursor = dataset.getStatements(null, null, null)) {
			while (cursor.hasNext()) {
				Statement statement = cursor.next();
				statements.add(values.createStatement((Resource) detach(statement.getSubject()),
						(IRI) detach(statement.getPredicate()), detach(statement.getObject()),
						(Resource) detach(statement.getContext())));
			}
		}
		return indexed(statements);
	}

	private static Value detach(Value value) {
		var values = SimpleValueFactory.getInstance();
		if (value == null) {
			return null;
		}
		if (value instanceof IRI iri) {
			return values.createIRI(iri.stringValue());
		}
		if (value instanceof BNode node) {
			return values.createBNode(node.getID());
		}
		Literal literal = (Literal) value;
		if (literal.getLanguage().isPresent()) {
			return values.createLiteral(literal.getLabel(), literal.getLanguage().orElseThrow(),
					literal.getBaseDirection());
		}
		return values.createLiteral(literal.getLabel(), values.createIRI(literal.getDatatype().stringValue()));
	}

	private static Map<String, Statement> indexed(List<Statement> statements) {
		Map<String, Statement> result = new LinkedHashMap<>();
		for (Statement statement : statements) {
			assertNull(result.put(subjectKey(statement), statement), "Fixture subjects must be unique");
		}
		return result;
	}

	private static String subjectKey(Statement statement) {
		Resource subject = statement.getSubject();
		return (subject instanceof BNode ? "B:" : "I:") + subject.stringValue();
	}

	private static byte[] exportedJournal(LmdbBackupServiceImpl service, Path backups, long from, long to,
			Path destination) throws IOException {
		List<Path> exported = service.exportTransactionLogs(backups, from, to, destination);
		assertEquals(1, exported.size());
		try (GZIPInputStream input = new GZIPInputStream(Files.newInputStream(exported.getFirst()))) {
			return input.readAllBytes();
		}
	}

	private static byte[] journal(List<Record> records, long previous, UUID generation) throws IOException {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.write(output, records, previous, generation);
		return output.toByteArray();
	}

	private static void assertRawRecords(byte[] bytes, Map<String, Statement> expected, boolean addition,
			long previous, UUID generation) throws IOException {
		var decoded = LmdbBackupDeltaCodec.readJournal(new ByteArrayInputStream(bytes));
		assertEquals(previous, decoded.previousTransactionId());
		assertEquals(generation, decoded.generation());
		assertEquals(expected.size(), decoded.records().size());
		ByteArrayOutputStream header = new ByteArrayOutputStream();
		LmdbBackupDeltaCodec.writeJournalHeader(new DataOutputStream(header), expected.size(), previous, generation);
		assertArrayEquals(header.toByteArray(), Arrays.copyOf(bytes, header.size()));
		ByteArrayInputStream raw = new ByteArrayInputStream(bytes, header.size(), bytes.length - header.size());
		DataInputStream input = new DataInputStream(raw);
		var seen = new HashSet<String>();
		for (int i = 0; i < expected.size(); i++) {
			int start = bytes.length - raw.available();
			Record record = LmdbBackupDeltaCodec.readRecord(input, SimpleValueFactory.getInstance());
			assertTrue(record.isStatementOperation());
			String key = subjectKey(record.getStatement());
			assertTrue(seen.add(key), "A captured statement must occur only once");
			Statement statement = expected.get(key);
			assertNotNull(statement, "A captured statement must match an expected physical subject");
			ByteArrayOutputStream expectedRecord = new ByteArrayOutputStream();
			LmdbBackupDeltaCodec.writeRecord(new DataOutputStream(expectedRecord),
					new Record(addition, true, statement));
			assertArrayEquals(expectedRecord.toByteArray(),
					Arrays.copyOfRange(bytes, start, bytes.length - raw.available()),
					"Captured record bytes must preserve the exact lexical representation for " + key);
		}
		assertEquals(0, raw.available(), "The journal must contain no trailing record bytes");
	}
